# The Complete Guide to Navigation, Data Persistence & Networking in Android

Modern Android apps need to navigate between screens, store data locally, and communicate with APIs. This guide covers the essential libraries and patterns for building robust, data-driven Android applications.

## Jetpack Navigation

Navigation component simplifies screen-to-screen navigation in Android.

### Setup

```kotlin
// build.gradle (app)
dependencies {
    val navVersion = "2.7.7"
    implementation("androidx.navigation:navigation-compose:$navVersion")
}
```

### Basic Navigation with Compose

```kotlin
@Composable
fun AppNavigation() {
    val navController = rememberNavController()

    NavHost(
        navController = navController,
        startDestination = "home"
    ) {
        composable("home") {
            HomeScreen(
                onNavigateToDetail = { id ->
                    navController.navigate("detail/$id")
                }
            )
        }

        composable(
            route = "detail/{itemId}",
            arguments = listOf(
                navArgument("itemId") { type = NavType.IntType }
            )
        ) { backStackEntry ->
            val itemId = backStackEntry.arguments?.getInt("itemId") ?: 0
            DetailScreen(
                itemId = itemId,
                onBack = { navController.popBackStack() }
            )
        }

        composable("settings") {
            SettingsScreen()
        }
    }
}
```

### Bottom Navigation

```kotlin
@Composable
fun MainScreen() {
    val navController = rememberNavController()
    val items = listOf(
        BottomNavItem("Home", Icons.Default.Home, "home"),
        BottomNavItem("Search", Icons.Default.Search, "search"),
        BottomNavItem("Profile", Icons.Default.Person, "profile")
    )

    Scaffold(
        bottomBar = {
            NavigationBar {
                val currentRoute = navController
                    .currentBackStackEntryAsState().value?.destination?.route

                items.forEach { item ->
                    NavigationBarItem(
                        icon = { Icon(item.icon, contentDescription = item.label) },
                        label = { Text(item.label) },
                        selected = currentRoute == item.route,
                        onClick = {
                            navController.navigate(item.route) {
                                popUpTo(navController.graph.startDestinationId)
                                launchSingleTop = true
                            }
                        }
                    )
                }
            }
        }
    ) { padding ->
        NavHost(
            navController = navController,
            startDestination = "home",
            modifier = Modifier.padding(padding)
        ) {
            composable("home") { HomeScreen() }
            composable("search") { SearchScreen() }
            composable("profile") { ProfileScreen() }
        }
    }
}
```

### Type-Safe Navigation

```kotlin
// Define routes as sealed classes
sealed class Screen(val route: String) {
    object Home : Screen("home")
    object Detail : Screen("detail/{id}") {
        fun createRoute(id: Int) = "detail/$id"
    }
    object Settings : Screen("settings")
}

// Usage
navController.navigate(Screen.Detail.createRoute(42))
```

## Room Database - Local Persistence

Room provides an abstraction layer over SQLite.

### Setup

```kotlin
dependencies {
    val roomVersion = "2.6.1"
    implementation("androidx.room:room-runtime:$roomVersion")
    implementation("androidx.room:room-ktx:$roomVersion")
    ksp("androidx.room:room-compiler:$roomVersion")
}
```

### Defining Entities

```kotlin
@Entity(tableName = "tasks")
data class Task(
    @PrimaryKey(autoGenerate = true)
    val id: Int = 0,
    val title: String,
    val description: String?,
    val isCompleted: Boolean = false,
    val priority: Int = 0,
    @ColumnInfo(name = "created_at")
    val createdAt: Long = System.currentTimeMillis()
)

@Entity(tableName = "categories")
data class Category(
    @PrimaryKey(autoGenerate = true)
    val id: Int = 0,
    val name: String,
    val color: String
)
```

### Data Access Objects (DAOs)

```kotlin
@Dao
interface TaskDao {
    @Query("SELECT * FROM tasks ORDER BY created_at DESC")
    fun getAllTasks(): Flow<List<Task>>

    @Query("SELECT * FROM tasks WHERE isCompleted = :completed")
    fun getTasksByStatus(completed: Boolean): Flow<List<Task>>

    @Query("SELECT * FROM tasks WHERE id = :id")
    suspend fun getTaskById(id: Int): Task?

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertTask(task: Task): Long

    @Update
    suspend fun updateTask(task: Task)

    @Delete
    suspend fun deleteTask(task: Task)

    @Query("DELETE FROM tasks WHERE isCompleted = 1")
    suspend fun deleteCompletedTasks()

    @Query("SELECT COUNT(*) FROM tasks WHERE isCompleted = 0")
    fun getPendingTaskCount(): Flow<Int>
}
```

### Database Setup

```kotlin
@Database(
    entities = [Task::class, Category::class],
    version = 1,
    exportSchema = true
)
abstract class AppDatabase : RoomDatabase() {
    abstract fun taskDao(): TaskDao

    companion object {
        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getDatabase(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "app_database"
                )
                .fallbackToDestructiveMigration()
                .build()
                .also { INSTANCE = it }
            }
        }
    }
}
```

### Repository Pattern

```kotlin
class TaskRepository(private val taskDao: TaskDao) {
    val allTasks: Flow<List<Task>> = taskDao.getAllTasks()
    val pendingCount: Flow<Int> = taskDao.getPendingTaskCount()

    suspend fun insert(task: Task) = taskDao.insertTask(task)
    suspend fun update(task: Task) = taskDao.updateTask(task)
    suspend fun delete(task: Task) = taskDao.deleteTask(task)
    suspend fun getById(id: Int) = taskDao.getTaskById(id)

    fun getByStatus(completed: Boolean) =
        taskDao.getTasksByStatus(completed)
}
```

### ViewModel with Room

```kotlin
class TaskViewModel(
    private val repository: TaskRepository
) : ViewModel() {

    val allTasks = repository.allTasks
        .stateIn(viewModelScope, SharingStarted.Lazily, emptyList())

    val pendingCount = repository.pendingCount
        .stateIn(viewModelScope, SharingStarted.Lazily, 0)

    fun addTask(title: String, description: String?) {
        viewModelScope.launch {
            repository.insert(
                Task(title = title, description = description)
            )
        }
    }

    fun toggleComplete(task: Task) {
        viewModelScope.launch {
            repository.update(
                task.copy(isCompleted = !task.isCompleted)
            )
        }
    }

    fun deleteTask(task: Task) {
        viewModelScope.launch {
            repository.delete(task)
        }
    }
}
```

## Retrofit - Networking

Retrofit is the standard HTTP client for Android.

### Setup

```kotlin
dependencies {
    implementation("com.squareup.retrofit2:retrofit:2.9.0")
    implementation("com.squareup.retrofit2:converter-gson:2.9.0")
    implementation("com.squareup.okhttp3:logging-interceptor:4.12.0")
}
```

### API Interface

```kotlin
interface ApiService {
    @GET("posts")
    suspend fun getPosts(): List<Post>

    @GET("posts/{id}")
    suspend fun getPost(@Path("id") id: Int): Post

    @POST("posts")
    suspend fun createPost(@Body post: CreatePostRequest): Post

    @PUT("posts/{id}")
    suspend fun updatePost(
        @Path("id") id: Int,
        @Body post: UpdatePostRequest
    ): Post

    @DELETE("posts/{id}")
    suspend fun deletePost(@Path("id") id: Int)

    @GET("posts")
    suspend fun searchPosts(
        @Query("q") query: String,
        @Query("page") page: Int = 1
    ): List<Post>
}
```

### Retrofit Client

```kotlin
object RetrofitClient {
    private const val BASE_URL = "https://api.example.com/"

    private val loggingInterceptor = HttpLoggingInterceptor().apply {
        level = HttpLoggingInterceptor.Level.BODY
    }

    private val authInterceptor = Interceptor { chain ->
        val request = chain.request().newBuilder()
            .addHeader("Authorization", "Bearer ${TokenManager.getToken()}")
            .build()
        chain.proceed(request)
    }

    private val okHttpClient = OkHttpClient.Builder()
        .addInterceptor(authInterceptor)
        .addInterceptor(loggingInterceptor)
        .connectTimeout(30, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .build()

    val apiService: ApiService = Retrofit.Builder()
        .baseUrl(BASE_URL)
        .client(okHttpClient)
        .addConverterFactory(GsonConverterFactory.create())
        .build()
        .create(ApiService::class.java)
}
```

### Handling API Responses

```kotlin
sealed class Result<out T> {
    data class Success<T>(val data: T) : Result<T>()
    data class Error(val message: String, val code: Int? = null) : Result<Nothing>()
    object Loading : Result<Nothing>()
}

class PostRepository(
    private val api: ApiService,
    private val postDao: PostDao
) {
    suspend fun getPosts(): Result<List<Post>> {
        return try {
            val posts = api.getPosts()
            // Cache in local database
            postDao.insertAll(posts)
            Result.Success(posts)
        } catch (e: HttpException) {
            Result.Error("Server error: ${e.code()}")
        } catch (e: IOException) {
            // Return cached data when offline
            val cached = postDao.getAllPosts().first()
            if (cached.isNotEmpty()) {
                Result.Success(cached)
            } else {
                Result.Error("No internet connection")
            }
        }
    }
}
```

## Offline-First Architecture

```kotlin
class OfflineFirstRepository(
    private val api: ApiService,
    private val dao: TaskDao
) {
    // Single source of truth: local database
    val tasks: Flow<List<Task>> = dao.getAllTasks()

    // Sync with server
    suspend fun refresh(): Result<Unit> {
        return try {
            val remoteTasks = api.getTasks()
            dao.deleteAll()
            dao.insertAll(remoteTasks)
            Result.Success(Unit)
        } catch (e: Exception) {
            Result.Error(e.message ?: "Sync failed")
        }
    }

    // Create locally, then sync
    suspend fun createTask(task: Task) {
        val localId = dao.insertTask(task)
        try {
            val remoteTask = api.createTask(task)
            dao.updateTask(task.copy(id = remoteTask.id))
        } catch (e: Exception) {
            // Task saved locally, will sync later
        }
    }
}
```

## DataStore - Key-Value Persistence

```kotlin
// For simple preferences, use DataStore instead of SharedPreferences
val Context.dataStore by preferencesDataStore(name = "settings")

class SettingsRepository(private val dataStore: DataStore<Preferences>) {
    private val DARK_MODE = booleanPreferencesKey("dark_mode")
    private val LANGUAGE = stringPreferencesKey("language")

    val darkMode: Flow<Boolean> = dataStore.data.map { prefs ->
        prefs[DARK_MODE] ?: false
    }

    suspend fun setDarkMode(enabled: Boolean) {
        dataStore.edit { prefs ->
            prefs[DARK_MODE] = enabled
        }
    }
}
```

## Best Practices

### Navigation
1. Use type-safe routes with sealed classes
2. Handle deep links for external navigation
3. Save and restore navigation state
4. Use nested navigation for complex flows

### Data Persistence
1. Use Room for structured data
2. Use DataStore for preferences
3. Follow the repository pattern
4. Use Flow for reactive data

### Networking
1. Always handle errors gracefully
2. Implement offline support
3. Use interceptors for auth and logging
4. Cache responses appropriately

## Conclusion

Navigation, persistence, and networking form the backbone of any Android application. Mastering these components enables you to build professional, data-driven apps.

**Key Takeaways:**
1. Use Jetpack Navigation for type-safe screen navigation
2. Room provides robust local data persistence
3. Retrofit simplifies API communication
4. Implement offline-first architecture for reliability
5. Follow the repository pattern for clean data access
6. Use Flow for reactive, observable data

Happy Android development!
